local _, RM = ...
if RM.LOCALE ~= "frFR" then return end
local L = RM.L

L["Ruinen von Ahn'Qiraj"] = "Ruines d'Ahn'Qiraj"
L["Kurinnaxx"] = "Kurinnaxx"
L["- Tödliche Wunde: stapelnder Debuff auf dem Tank, reduziert erhaltene Heilung -> Tankwechsel bei hohen Stapeln."] = "- Blessure mortelle : debuff cumulable sur le tank, réduit les soins reçus -> changement de tank à beaucoup de stacks."
L["- Sandfalle: erscheint unter einem Spieler und lässt ihn bei Auslösen verfehlen -> sofort herauslaufen."] = "- Piège de sable : apparaît sous un joueur et le fait rater ses attaques quand il se déclenche -> sortir immédiatement."
L["- Raserei bei ca. 30 %: deutlich mehr Schaden -> Heiler auf die Tanks, Schaden hochfahren."] = "- Frénésie vers 30 % : dégâts nettement accrus -> heals sur les tanks, monter le DPS."
L["Taktik: Zwei Tanks wechseln sich ab, Raid verteilt hinter dem Boss, Sandfallen sofort verlassen."] = "Tactique : deux tanks alternent, raid réparti derrière le boss, quitter immédiatement les Pièges de sable."
L["KURINNAXX: Tankwechsel bei Tödlicher Wunde! Raus aus der Sandfalle!"] = "KURINNAXX : changement de tank sur Blessure mortelle ! Sortez du Piège de sable !"
L["Ab 30 % Raserei: Heiler auf die Tanks, alles auf den Boss."] = "À 30 % Frénésie : heals sur les tanks, tout le monde sur le boss."
L["General Rajaxx + Wellen der Qiraji (mit Generalleutnant Andorov)"] = "Général Rajaxx + vagues de Qiraji (avec le lieutenant général Andorov)"
L["- Wellen: mehrere Wellen Qiraji-Krieger mit je einem Hauptmann greifen nacheinander an -> Hauptmann und Adds sauber abarbeiten."] = "- Vagues : plusieurs vagues de guerriers qiraji, chacune avec un capitaine, attaquent l'une après l'autre -> gérer proprement capitaine et adds."
L["- Andorov: NPC-Verbündeter mit Aura und Händler -> am Leben halten, er hilft bei den Wellen."] = "- Andorov : allié PNJ avec aura et marchand -> le garder en vie, il aide pendant les vagues."
L["- Donnerkrachen (Rajaxx): halbiert das aktuelle Leben aller Spieler in der Nähe -> Raid hoch halten, Abstand für Fernkampf."] = "- Fracas de tonnerre (Rajaxx) : réduit de moitié la vie actuelle de tous les joueurs proches -> garder le raid full vie, distance pour les distants."
L["- Entwaffnen/Ansturm-Fähigkeiten der Hauptleute: Tankschaden schwankt -> Heiler aufmerksam."] = "- Désarmement/charge des capitaines : les dégâts sur le tank varient -> heals attentifs."
L["Taktik: Wellen am Startpunkt tanken und mit Flächenschaden töten, zwischen den Wellen regenerieren. Zum Schluss Rajaxx tanken und mit allem töten."] = "Tactique : tanker les vagues au point de départ et les tuer en AoE, regen entre les vagues. À la fin, tanker Rajaxx et le tuer avec tout."
L["RAJAXX: Wellen sauber abarbeiten, Andorov am Leben halten!"] = "RAJAXX : gérez proprement les vagues, gardez Andorov en vie !"
L["Donnerkrachen halbiert Leben: Raid immer voll heilen."] = "Fracas de tonnerre divise la vie par deux : toujours remonter le raid full vie."
L["Moam + Manadämonen"] = "Moam + démons de mana"
L["- Mana entziehen: Moam saugt Mana der Spieler; bei vollem Mana Arkanausbruch auf den ganzen Raid -> sein Mana leer halten (Mana verbrennen, Vipernbiss, Mana entziehen)."] = "- Drain de mana : Moam aspire le mana des joueurs ; mana plein = Éruption des arcanes sur tout le raid -> garder son mana vide (Brûlure de mana, Morsure de vipère, Drain de mana)."
L["- Versteinern: Moam wird zu Stein und ruft Manadämonen -> Dämonen verbannen bzw. tanken und töten."] = "- Pétrification : Moam se change en pierre et invoque des démons de mana -> bannir les démons ou les tanker et les tuer."
L["- Manadämonen: Arkanschaden und Spalten -> nicht frei laufen lassen."] = "- Démons de mana : dégâts des arcanes et Enchaînement -> ne pas les laisser libres."
L["Taktik: Schnell Schaden machen, Jäger/Priester/Hexer halten sein Mana unten. Bei Versteinerung Hexer auf die Manadämonen einteilen."] = "Tactique : DPS rapide, chasseurs/prêtres/démonistes gardent son mana bas. Pendant la pétrification, assigner les démonistes aux démons de mana."
L["MOAM: Sein Mana leer halten! Bei Stein: Manadämonen verbannen!"] = "MOAM : gardez son mana à zéro ! En pierre : bannissez les démons de mana !"
L["Jäger Vipernbiss, Priester Mana verbrennen, Hexer Mana entziehen."] = "Chasseurs Morsure de vipère, prêtres Brûlure de mana, démonistes Drain de mana."
L["Moam (Dämonen)"] = "Moam (démons)"
L["Jeder Manadämon ein Symbol, je ein Hexer verbannt sein zugewiesenes Symbol."] = "Une marque par démon de mana, chaque démoniste bannit sa marque assignée."
L["Buru der Verschlinger + Eier"] = "Buru Grand-Gosier + œufs"
L["- Fixieren: Buru verfolgt einen zufälligen Spieler -> diesen Spieler Buru in ein Ei ziehen lassen."] = "- Fixation : Buru poursuit un joueur au hasard -> ce joueur fait passer Buru dans un œuf."
L["- Eier: zerstörte Eier explodieren und verletzen Buru (und Spieler in der Nähe), es schlüpfen Brutlinge -> Eier nur zerschlagen, wenn Buru danebensteht, Abstand halten."] = "- Œufs : les œufs détruits explosent et blessent Buru (et les joueurs proches), des Couveurs éclosent -> ne casser les œufs que si Buru est à côté, garder la distance."
L["- Phase 2 (ca. 20 %): Buru verliert Panzer, kriechende Seuche verursacht steigenden Raidschaden -> alles auf den Boss."] = "- Phase 2 (vers 20 %) : Buru perd sa carapace, Peste rampante inflige des dégâts croissants au raid -> tout sur le boss."
L["Taktik: Raid zerschlägt Eier gezielt, wenn Buru den fixierten Spieler durch ein Ei verfolgt; Brutlinge schnell töten. Ab 20 % voller Schaden."] = "Tactique : le raid casse les œufs au bon moment quand Buru poursuit le joueur fixé à travers un œuf ; tuer vite les Couveurs. À 20 %, full DPS."
L["BURU: Fixierten Spieler -> Buru durch die Eier ziehen! Abstand zur Explosion!"] = "BURU : joueur fixé -> amenez Buru à travers les œufs ! Distance avec l'explosion !"
L["Bei 20 % alles auf Buru, Heiler Raid hoch halten."] = "À 20 % tout sur Buru, heals gardez le raid full vie."
L["Ayamiss der Jäger + Larven/Wespen"] = "Ayamiss le Chasseur + larves/guêpes"
L["- Phase 1 in der Luft: nur Fernkampf erreicht sie -> Fernkampf auf den Boss, Nahkampf auf Adds."] = "- Phase 1 en l'air : seuls les distants l'atteignent -> distants sur le boss, CàC sur les adds."
L["- Lähmen: ein Spieler wird auf den Altar gebracht, eine Larve läuft hin -> Larve sofort töten, sonst stirbt der Spieler."] = "- Paralysie : un joueur est placé sur l'autel, une larve s'en approche -> tuer la larve immédiatement, sinon le joueur meurt."
L["- Giftstachelsalve: Naturschaden auf viele Spieler -> Gift entfernen, Naturwiderstand hilft."] = "- Salve de dards empoisonnés : dégâts de nature sur beaucoup de joueurs -> dispel le poison, la résistance nature aide."
L["- Phase 2 (ca. 70 %): landet und wird getankt, ruft weiter Wespen -> Tank übernimmt, Adds mit Flächenschaden töten."] = "- Phase 2 (vers 70 %) : elle atterrit et se fait tanker, continue d'appeler des guêpes -> le tank prend, tuer les adds en AoE."
L["Taktik: Fernkampf schießt den Boss herunter, Nahkampf kümmert sich um Larven und Wespen. Nach der Landung normal tanken."] = "Tactique : les distants descendent le boss, le CàC s'occupe des larves et des guêpes. Après l'atterrissage, tanking normal."
L["AYAMISS: Larve zum Altar sofort töten! Fernkampf auf den Boss!"] = "AYAMISS : tuez immédiatement la larve qui va à l'autel ! Distants sur le boss !"
L["Gift entfernen. Ab 70 % landet sie: Tank bereit."] = "Dispel le poison. À 70 % elle atterrit : tank prêt."
L["Ossirian der Narbenlose"] = "Ossirian l'Intouché"
L["- Stärke des Ossirian: ohne Schwäche fast unverwundbar und tödlich -> immer zu einem Kristall ziehen."] = "- Force d'Ossirian : sans faiblesse, presque invulnérable et mortel -> toujours l'amener à un cristal."
L["- Kristalle: Aktivieren gibt ihm eine Zauberschwäche für ca. 45 Sek. -> rechtzeitig nächsten Kristall aktivieren und Boss dorthin tanken."] = "- Cristaux : l'activation lui donne une faiblesse à une école de magie pendant env. 45 s -> activer le cristal suivant à temps et y tanker le boss."
L["- Wirbelstürme: wandern durch den Raum -> ausweichen."] = "- Cyclones : se déplacent dans la salle -> esquiver."
L["- Fluch der Sprachen/Umhüllende Winde/Kriegsdonner: Raidkontrolle -> entfluchen, Abstand halten."] = "- Malédiction des langages/Vents enveloppants/Choc martial : contrôle du raid -> decurse, garder la distance."
L["Taktik: Tank kitet Ossirian von Kristall zu Kristall, ein Spieler aktiviert den nächsten vor Ablauf der Schwäche. Schaden passend zur Schwäche-Schule."] = "Tactique : le tank kite Ossirian de cristal en cristal, un joueur active le suivant avant la fin de la faiblesse. DPS adapté à l'école de la faiblesse."
L["OSSIRIAN: Nächsten Kristall rechtzeitig aktivieren! Schwäche nie ablaufen lassen!"] = "OSSIRIAN : activez le cristal suivant à temps ! Ne laissez jamais tomber la faiblesse !"
L["Wirbelstürmen ausweichen, Flüche entfernen."] = "Esquivez les cyclones, retirez les malédictions."
L["Tempel von Ahn'Qiraj"] = "Temple d'Ahn'Qiraj"
L["Der Prophet Skeram + 2 Abbilder"] = "Le Prophète Skeram + 2 images"
L["- Arkane Explosion: hoher Flächenschaden -> unterbrechen, Nahkampf vorsichtig."] = "- Explosion des arcanes : grosse AoE -> interrompre, CàC prudent."
L["- Wahre Erfüllung: Gedankenkontrolle -> Spieler kontrollieren (Verwandlung, Furcht), nicht töten."] = "- Accomplissement véritable : contrôle mental -> contrôler le joueur (Métamorphose, Peur), ne pas le tuer."
L["- Teleport: Skeram springt auf eine andere Plattform und setzt die Bedrohung zurück -> auf jeder Plattform ein Tank."] = "- Téléportation : Skeram saute sur une autre plateforme et réinitialise la menace -> un tank sur chaque plateforme."
L["- Abbilder bei 75/50/25 %: zwei Kopien erscheinen -> Kopien tanken, echten Skeram finden und töten."] = "- Images à 75/50/25 % : deux copies apparaissent -> tanker les copies, trouver et tuer le vrai Skeram."
L["Taktik: Drei Tanks auf drei Positionen verteilen, Unterbrecher fest einteilen. Bei Abbildern echten Skeram markieren und zuerst töten."] = "Tactique : répartir trois tanks sur trois positions, assigner les interrupts. Avec les images, marquer le vrai Skeram et le tuer en premier."
L["SKERAM: Arkane Explosion unterbrechen! Gedankenkontrolle kontrollieren, nicht töten!"] = "SKERAM : interrompez l'Explosion des arcanes ! Contrôlez les mind control, ne les tuez pas !"
L["Bei Abbildern nur auf den echten Skeram (Totenkopf)."] = "Avec les images, uniquement sur le vrai Skeram (Crâne)."
L["Skeram"] = "Skeram"
L["Totenkopf auf den echten Skeram, Kreuz und Viereck auf die Abbilder."] = "Crâne sur le vrai Skeram, Croix et Carré sur les images."
