L["|cff40ff40Raid läuft seit %s|r (%s) · %d Bosse besiegt"] = "|cff40ff40Raid en cours depuis %s|r (%s) · %d boss vaincus"
L["%d Spieler · Tanks %d · Heiler %d · Nahkampf %d · Fernkampf %d"] = "%d joueurs · tanks %d · soigneurs %d · mêlée %d · distance %d"
